from collections import defaultdict


def parse_query(query: str) -> dict[str, list[str]]:
    if not query:
        return {}

    if query.startswith("?"):
        query = query[1:]

    if not query:
        return {}

    def decode(s: str) -> str:
        s = s.replace("+", " ")
        if "%" not in s:
            return s

        parts = s.split("%")
        res = [parts[0]]
        for part in parts[1:]:
            if len(part) >= 2:
                hex_digits = part[:2]
                try:
                    byte_val = int(hex_digits, 16)
                    decoded_char = bytes([byte_val]).decode("utf-8", errors="replace")
                    res.append(decoded_char + part[2:])
                    continue
                except ValueError:
                    pass
            res.append("%" + part)
        return "".join(res)

    result: dict[str, list[str]] = defaultdict(list)

    for piece in query.split("&"):
        if not piece:
            continue

        if "=" in piece:
            key, value = piece.split("=", 1)
        else:
            key, value = piece, ""

        decoded_key = decode(key)
        decoded_value = decode(value)

        result[decoded_key].append(decoded_value)

    return dict(result)
